import {Component, HostListener, OnInit, ViewEncapsulation} from '@angular/core';
import {Router} from "@angular/router";
import {LanguageService} from "../../services/language/language.service";


@Component({
    selector: 'app-terminal',
    templateUrl: './terminal.component.html',
    styleUrls: ['./terminal.component.scss'],
    encapsulation: ViewEncapsulation.None
})
export class TerminalComponent implements OnInit {
    lines: string[] = [];
    waitForInput = false;
    fullscreen = false;
    loading = true;

    constructor(private router: Router, private languageService: LanguageService) {
    }

    async ngOnInit() {
        if (this.terminal) {
            await this.wait(1000);
            this.loading = false;
            await this.createLine(`last login: ${new Date().toLocaleString()}`);
            await this.createLine('# in /users/arun-varghese', 500);
            await this.createCode('here are some commands you can run:', 'help | clear | exit', 50);
            this.createNewLine();
            await this.wait(50);
            this.waitForInput = true;
        }
    }

    @HostListener('window:click', ['$event.target'])
    async click(element: HTMLElement) {
        if (element.classList.contains('t-link')) {
            this.input.value = `open ${element.innerText}`;
            await this.inputActive();
        }
    }

    @HostListener('window:keyup', ['$event'])
    async submitInput(event: KeyboardEvent) {
        if (this.terminal && event.key == 'Enter') {
            const value = this.input?.value;
            this.clearInput();
            await this.checkInputValue(value?.toLowerCase()?.trim() || '');
            await this.inputActive();
        }
    }

    clearInput() {
        if (this.input?.value) {
            this.input.value = '';
        }
        this.waitForInput = false;
    }

    async inputActive() {
        this.waitForInput = true;
        await this.wait(100);
        if (this.input && this.anchor) {
            this.input.focus();
            await this.wait(100);
            this.anchor?.scrollIntoView();
        }
    }

    get terminal() {
        return document.getElementById('terminal');
    }

    get input() {
        return document.getElementById('terminal-input') as HTMLInputElement;
    }

    get anchor() {
        return document.getElementById('anchor');
    }

    createNewLine() {
        this.lines.push('<br>');
    }

    async createLine(text: string, delay = 50) {
        await this.wait(delay);
        this.lines.push(text);
        this.anchor?.scrollIntoView();
    }

    async createSuccessLine(text: string, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<span class='t-green'>$ ${text} </span>`);
        this.createNewLine();
        this.anchor?.scrollIntoView();
    }

    async createErrorLine(text: string, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<span class='t-red'>$ ${text} </span>`);
        this.createNewLine();
        this.anchor?.scrollIntoView();
    }

    async createHelpLine(command, desc, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<div class='t-blue t-tab-1 t-help-command'>${command}</div><span> ${desc} </span>`);
        this.anchor?.scrollIntoView();
    }

    async createCode(code, text, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<span class="t-blue">${code}</span><br/><span class='t-text'> ${text} </span>`);
        this.anchor?.scrollIntoView();
    }

    async createContactLine(link, icon, label, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<a href='${link}' target='_blank' class="t-tab-1"><i class='${icon} white'></i>&nbsp;${label}</a>`);
        this.anchor?.scrollIntoView();
    }

    async createTabbedLine(text, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<span class='t-tab-1'>${text}</span>`);
        this.anchor?.scrollIntoView();
    }

    async createNavigationLine(link, delay = 50) {
        await this.wait(delay);
        this.lines.push(`<a class='t-link t-tab-1'>${link}</a>`);
        this.anchor?.scrollIntoView();
    }

    navigate(item) {
        this.router.navigate([item]);
    }

    exitTerminal() {
        this.router.navigate(['home']);
    }

    wait = ms => new Promise(resolve => setTimeout(resolve, ms))

    async checkInputValue(value: string) {
        if (value === 'help') {
            await this.createSuccessLine(value, 100);
            await this.createLine('usage:', 100);
            await this.createNewLine();
            await this.createHelpLine('about', 'who am i');
            await this.createHelpLine('contact', 'contact me');
            await this.createHelpLine('open', 'open &lt;page&gt;');
            await this.createHelpLine('clear', 'clear terminal');
            await this.createHelpLine('exit', 'close terminal');
            await this.createNewLine();
        } else if (value === 'about') {
            await this.createSuccessLine(value);
            await this.createLine('hi, my name is <span class="t-blue">arun</span>')
            await this.createLine('i have over 10 years of full-stack experience in the complete development life cycle of distributed web applications, from design to delivery.');
            await this.createLine('in my free time, I work on front-end web development with popular frameworks to learn more about ui/ux and software architecture');
            await this.createNewLine();
        } else if (value === 'open') {
            await this.createSuccessLine(value);
            await this.createLine('choose page:');
            await this.createNewLine();
            await this.createNavigationLine('highlights');
            await this.createNavigationLine('experience');
            await  this.createNavigationLine('projects');
            await this.createNavigationLine('resume');
            await this.createNewLine();
        } else if (value === 'open highlights') {
            this.navigate('highlights');
        } else if (value === 'open experience') {
            this.navigate('experience');
        } else if (value === 'open projects') {
            this.navigate('projects');
        } else if (value === 'open resume') {
            await this.createSuccessLine(value);
            this.languageService.translateService.get("Resume").subscribe(val => {
                window.open(val, "_blank");
            });
        } else if (value === 'contact') {
            await this.createSuccessLine(value);
            await this.createContactLine('mailto:arunv4700@gmail.com', 'fas fa-envelope', 'email');
            await this.createContactLine('https://www.linkedin.com/in/varghesearun', 'fab fa-linkedin', 'linkedin');
            await this.createContactLine('https://github.com/vararun', 'fab fa-github', 'github');
            await this.createContactLine('https://codepen.io/avarghese', 'fab fa-codepen', 'codepen');
            await this.createContactLine('https://www.instagram.com/chasing_arun', 'fab fa-instagram white', 'instagram');
            this.createNewLine();
        } else if (value === 'exit') {
            await this.createErrorLine(value);
            this.navigate('home');
        } else if (value === 'clear') {
            await this.createSuccessLine(value);
            this.waitForInput = false;
            this.lines = [];
            this.waitForInput = true;
        } else if (value === '') {
            await this.createLine('$');
            return;
        } else {
            await this.createErrorLine(value);
            await this.createLine(`command not found: ${value}`)
            this.createNewLine();
        }
    }
}
